"""Assemble the scientific interpretation, email text and reproducibility manifest."""
from pathlib import Path
import json,html,hashlib,platform,importlib.metadata
import numpy as np,pandas as pd
from real_trajectory_velocity import OUT,HERE

def esc(s):return html.escape(str(s))
def main():
    out=OUT;summary=json.loads((out/'run_summary.json').read_text());synthetic=json.loads((out/'synthetic/benchmark_summary.json').read_text());figs=json.loads((out/'trajectory_report_manifest.json').read_text())
    fields=pd.read_csv(out/'field_diagnostics.csv');raw=pd.read_csv(out/'raw_vs_fitted_projection.csv');root=pd.read_csv(out/'broad_reference_connections.csv')
    display=fields[['interval','supported_changing','displayed_2d','displayed_positive_net','displayed_negative_net','displayed_fitted_mixed_celltype_signs']].copy()
    display.columns=['Interval (hpf)','Changing sources','2D arrows eligible','Positive net','Negative net','Mixed fitted CT signs']
    fit=synthetic['fitted_evaluation'];baseline=synthetic['raw_evaluation'];two=raw[raw.embedding=='umap2d']
    high=fields.iloc[fields.displayed_2d.argmax()];low=fields.iloc[fields.displayed_2d.argmin()]
    mainfinding=f"The five intervals have {int(low.displayed_2d):,}–{int(high.displayed_2d):,} peaks eligible for 2D arrows ({100*low.displayed_2d/summary['n_peaks']:.1f}–{100*high.displayed_2d/summary['n_peaks']:.1f}% of the atlas). Each interval contains both positive and negative net relative accessibility changes."
    inference="Among displayed peaks, positive net changes are more common at 10–14 hpf, and negative net changes at 16–24 hpf. These are relative, selection-dependent patterns. My interpretation: the atlas supports several temporal opening/closing programs, rather than one compulsory outward flow from a universal root. The broad-accessibility reference is descriptive: being accessible at every stage does not require an unchanged accessibility level. An arrow connects neighboring fixed peaks with compatible profiles; it does not mean one genomic locus becomes another."
    weights='Fit-weight sensitivity results are saved separately when available; they compare precision weighting, not the CPM normalization itself.'
    sf=out/'weight_sensitivity/weight_sensitivity_summary.json'
    if sf.exists():
        ws=json.loads(sf.read_text());ret=[r['primary_source_retention'] for r in ws['fixed_panel_sources']];sg=[r['joint_supported_sign_agreement'] for r in ws['fixed_panel_interval_rates'] if r['scope']=='all_finite']
        weights=f"On 8,192 uniformly sampled peaks, equal-stage rather than coverage weights preserve {100*min(sg):.1f}–{100*max(sg):.1f}% of signs among CT changes supported by both fits, but retain only {100*min(ret):.1f}–{100*max(ret):.1f}% of the primary candidate arrow sources. Mode agreement is only 47.7% among fixed-panel trajectories called changing by either fit. Thus inclusion and mode calls are materially weight-sensitive; shared-sign agreement must not hide this selection sensitivity. This comparison changes fitting weights, not CPM normalization or depth. See weight_sensitivity/weight_sensitivity_summary.json."
    geometry=f"Among displayed arrows with a nontrivial graph-only direction, median alignment cosine with that direction is {fields.iloc[0].median_baseline_direction_cosine:.2f} at 10–12 hpf and {fields.iloc[-1].median_baseline_direction_cosine:.2f} at 19–24 hpf. Agreement alone does not identify how much direction is biological versus geometric."
    body=f'''<h1>Six-stage chromatin accessibility dynamics</h1><p>{esc(mainfinding)}</p><p>{esc(inference)}</p>
    <h2>What was computed</h2><ul>
    <li><b>640,830 genomic peaks × 32 celltypes × six developmental times:</b> 10, 12, 14, 16, 19 and 24 hpf. Every UMAP dot is a peak. The published 2D/3D coordinates and neighbor graph were reused exactly.</li>
    <li>Fit linear CPM accessibility using a constant, line, or continuous one-turn model with a hinge at 14 or 16 hpf. Select with weighted leave-one-stage-out error plus a complexity penalty. Missing or low-cell-count conditions stay unavailable; no zero imputation or derivative across missing stages.</li>
    <li>Calculate five fitted adjacent differences divided by the actual time gaps. Assign increasing, decreasing, transient peak, transient trough, no-supported-change, uncertain, or insufficient modes. Incomplete evidence for both phases of a fitted reversal is uncertain.</li>
    <li>The primary projection uses 21 celltypes with ≥20 cells at every stage, equally weighted in the state-space cosine. Low-count closed states remain useful coordinates. Counts and conditional uncertainty gate source changes separately.</li>
    <li>Use uncentered cosine between a source peak's fitted change and neighbor-minus-source current-stage celltype profiles on the original graph. This retains uniform opening across celltypes. No root, entropy, tau, ancestry, or Cicero coupling orients this field. No UMAP was recomputed.</li>
    <li>Display only sources with supported changes, adequate vector signal, shared features, aligned neighbors and coherent projected direction. Arrow lengths are display units; CPM/hpf magnitude is saved separately. Streamlines are local summaries of this interval field, not trajectories across genomic loci.</li></ul>
    <h2>Real-data result</h2>{display.to_html(index=False,border=0)}
    <p>Counts refer to eligible full-atlas arrows; figures and HTML display subsets for readability. Positive/negative refer to the equally weighted net rate over estimable, quality-filtered celltypes in the fixed candidate panel. Mixed fitted CT signs are descriptive and need not be individually significant. Opposing CT changes can cancel in the signed mean; inspect RMS change and celltype curves as well.</p>
    <p>Raw-versus-fitted direction agreement is evaluated only at sources where both methods yield supported arrows. These fields need not match: denoising across all stages changes local rates and source eligibility. The comparison table is saved as raw_vs_fitted_projection.csv.</p>
    <h2>Ground-truth benchmark and parameter choice</h2>
    <p>Calibration used seed 42; a separate seed 43, from the same simulator, tested 1,680 peaks × 20 celltypes. Settings were frozen before the real run: complexity penalty 0.2, conditional SE multiplier 3.5, practical rate floor 0.05 CPM/hpf, ≥20 total counts for mode/change claims, and vector SNR ≥2. A small synthetic fit-parameter sweep selected a conservative operating point; the real UMAP was not optimized for appearance. Projection cutoffs were kept fixed, not exhaustively tuned.</p>
    <p>Held-out macro rate RMSE across broad-program/control families (excluding the narrow-pulse and technical-spike families): <b>{baseline['macro_rate_rmse']:.3f} → {fit['macro_rate_rmse']:.3f} CPM/hpf</b>. Strong-program source-activation recall before graph projection (amplitude ≥5 CPM): <b>{100*baseline['strong_source_active_recall']:.1f}% → {100*fit['strong_source_active_recall']:.1f}%</b>. Worst stationary-control fraction of peaks activated in at least one interval: <b>{100*fit['worst_stationary_source_peak_fp']:.1f}%</b>. Strong broad-reversal recall: {100*fit['strong_broad_reversal_recall']:.1f}%. These are simulator results, not biological validation. The original calibration recall targets were not all met; the frozen setting prioritizes false-positive control.</p>
    <h2>Robustness matters</h2><p><b>{esc(weights)}</b></p><p>{esc(geometry)}</p>
    <h2>What remains unresolved</h2><ul>
    <li><b>Narrow pulses:</b> a genuine one-stage pulse can look exactly like a technical spike with these six snapshots. This model suppresses many such pulses. Withheld arrows and no-supported-change labels do not prove stable biology; observed curves and uncertain peaks are retained.</li>
    <li><b>Relative accessibility:</b> CPM divides by total condition coverage. The analysis preserves CPM amplitude and does not min–max each trajectory or require depth downsampling. Coverage weights affect fitting precision. CPM cannot establish genome-wide absolute opening/closing because global scale has been removed. See the weight-sensitivity section above.</li>
    <li><b>Uncertainty:</b> conditional Poisson count-noise approximations omit biological overdispersion and full model-selection uncertainty. SNR and fit-quality thresholds are heuristics, not calibrated biological confidence intervals.</li>
    <li><b>Geometry:</b> the UMAP graph was built from whole-course profiles, while each field uses a current-stage state. Its local geometry can bias arrows. field_diagnostics.csv compares against the graph-only geometric direction; broad_reference_connections.csv compares transitions to the broad reference with graph-only baseline connectivity. A visually coherent streamline is not a causal trajectory.</li>
    <li><b>Annotations:</b> promoter, intergenic, intronic and exonic peaks are retained and summarized separately. An intronic label does not rule out enhancer activity; these fields do not establish enhancer function or target genes.</li></ul>
    <h2>Recommended interpretation and follow-up</h2><p>Use this as an exploratory map of temporal regulatory programs and a route to individual peak × celltype curves. Prioritize broad changes that survive weighting checks and agree with independent biological evidence. Use the six-stage mode panel to identify reversals, then inspect each interval. Before treating the field as a biological mechanism, validate selected loci, incorporate biological replication where available, and assess narrow-pulse alternatives separately.</p>
    <h2>Files and reuse</h2><ul><li><a href="trajectory_peak_explorer.html">Interactive 2D/3D peak explorer</a> — an offline sampled display with peak/gene search and measured/fitted curves.</li><li>trajectory_fits.h5 — complete 32-celltype states, fits, rates, conditional SEs, mode labels, masks, and projection results.</li><li>trajectory_velocity.h5ad — 21-celltype AnnData with six observed/fitted states, five interval velocity layers, fixed UMAPs, original graph, sparse interval transitions, and diagnostics. X/velocity/velocity_umap use 10→12 hpf by default; other intervals are explicitly named.</li><li>CSV/JSON files record inputs, missing combinations, cluster/genomic summaries, raw comparisons, geometry diagnostics, validation, and the synthetic calibration.</li></ul>
    <p>Source scripts: real_trajectory_velocity.py, trajectory_modes.py, trajectory_classification.py, trajectory_projection.py, trajectory_benchmark.py, trajectory_report.py, trajectory_artifacts.py, verify_trajectory_velocity.py, and this report builder. Existing source atlas files are unchanged.</p>
    <h2>Method context</h2><p>The <a href="https://scvelo.readthedocs.io/en/stable/scvelo.tl.velocity_graph.html">scVelo transition-graph idea</a> motivates neighborhood projection. This implementation deliberately uses an uncentered cosine, rather than scVelo's centered correlation, to retain common-mode accessibility changes. It does not use RNA splicing kinetics.</p>
    <h2>Figures</h2>'''
    for fig in figs['figures']:
        body+=f'<section><h3>{esc(fig["stem"])}</h3><a href="{esc(fig["png"])}"><img src="{esc(fig["png"])}" alt="{esc(fig["stem"])}"></a><p>{esc(fig["caption"])}</p></section>'
    extra_figures=[('weight_sensitivity/01_fit_weight_sensitivity.png','Fit-weight sensitivity'),('synthetic/01_synthetic_trajectories.png','Synthetic measured and fitted trajectories'),('synthetic/02_synthetic_rate_metrics.png','Synthetic rate benchmark'),('synthetic/03_synthetic_mode_confusion.png','Synthetic mode classification'),('synthetic/04_synthetic_source_detection.png','Synthetic changing-source detection')]
    for path,label in extra_figures:
        if (out/path).exists():body+=f'<section><h3>{esc(label)}</h3><img src="{esc(path)}" alt="{esc(label)}"></section>'
    style='body{max-width:1120px;margin:32px auto;padding:0 24px;font:16px/1.55 system-ui;color:#203246}h1,h2{line-height:1.2}h2{margin-top:36px}img{width:100%;height:auto}table{border-collapse:collapse;font-size:14px}td,th{padding:8px 12px;border-bottom:1px solid #ccd3da;text-align:right}a{color:#09678d}li{margin-bottom:8px}'
    (out/'analysis_summary.html').write_text('<!doctype html><meta charset="utf-8"><title>Chromatin accessibility dynamics — analysis</title><style>'+style+'</style>'+body)
    email=f'''<p>Hello,</p><p>I completed the six-stage trajectory prototype on the real atlas, with the PNGs attached.</p><p><b>{esc(mainfinding)}</b></p><p>{esc(inference)}</p><ul><li>Fit all six measured stages for each peak × celltype, then derive five opening/closing rates using the actual time gaps. Keep the original 2D/3D UMAPs fixed and let accessibility changes orient the arrows.</li><li>Fit 640,830 peaks across 32 celltypes; use the 21 adequately sampled celltypes at every stage for the main projection. Missing observations remain missing. Retain promoter, intergenic, intronic and exonic peaks.</li><li>Held-out synthetic broad-program/control rate error (excluding narrow-pulse/spike families) fell {baseline['macro_rate_rmse']:.3f} → {fit['macro_rate_rmse']:.3f} CPM/hpf, with {100*fit['strong_source_active_recall']:.1f}% strong-program source-activation recall before graph projection (amplitude ≥5 CPM) and a worst stationary-control fraction activated in any interval of {100*fit['worst_stationary_source_peak_fp']:.1f}%. Parameters were calibrated on synthetic data and frozen for the real run; the real field was not selected for appearance.</li></ul><p><b>Weighting sensitivity:</b> {esc(weights)}</p><p>{esc(geometry)}</p><p><b>Main limitation:</b> six-stage fits recover broad patterns but suppress many narrow one-stage pulses. No arrow does not establish no biological change. Conditional count-noise diagnostics are not biological confidence intervals. CPM changes remain relative; this run does not require depth downsampling or support claims of absolute genome-wide opening.</p>{display.to_html(index=False,border=0)}<p>The interactive HTML explorer, report, full fits, AnnData export, CSV summaries, and reproducible scripts are saved here:<br><code>{esc(str(out))}</code></p><p>I will include a 15,000-peak offline display viewer in this thread as a separate ZIP; it uses the same full-model results. The larger 30,000-peak viewer and full 640,830-peak arrays remain at the path above. My recommendation is to use the mode and interval panels to identify broad candidate programs, then inspect measured/fitted celltype curves and validate individual loci before making mechanistic claims.</p><p>Best,<br>Codex</p>'''
    package=out/'email_package';package.mkdir(exist_ok=True);(package/'email_body.html').write_text(email)
    versions={x:importlib.metadata.version(x) for x in ['numpy','scipy','pandas','anndata','h5py','matplotlib','plotly']}
    sources=list((HERE.parents[1]/'scripts/chrom_velo').glob('trajectory_*.py'))+[HERE/x for x in ['real_trajectory_velocity.py','trajectory_report.py','trajectory_benchmark.py','trajectory_artifacts.py','verify_trajectory_velocity.py','trajectory_weight_sensitivity.py','plot_trajectory_weight_sensitivity.py','finish_trajectory_report.py']]
    manifest={'python':platform.python_version(),'libraries':versions,'sources_sha256':{str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in sources},'outputs':[{'path':str(p.relative_to(out)),'bytes':p.stat().st_size} for p in sorted(out.rglob('*')) if p.is_file() and 'email_package' not in p.parts], 'reproduce':['python trajectory_benchmark.py --frozen-only','python real_trajectory_velocity.py --stage all','python trajectory_artifacts.py --stage all','python verify_trajectory_velocity.py','python trajectory_weight_sensitivity.py','python finish_trajectory_report.py'],'tests':'37 unittest trajectory checks passed; saved validation_unit_tests.txt'}
    (out/'artifact_manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
    print(mainfinding)
if __name__=='__main__':main()
